#include <stdio.h>
#include <stdint.h>
int main(void){
  uint32_t v=0x01020304u;
  unsigned char *p=(unsigned char*)&v;
  printf("%02x %02x %02x %02x\n", p[0],p[1],p[2],p[3]);
  // portable network order demo (Windows needs Winsock2, POSIX uses arpa/inet.h)
  return 0;
}

#include <stdio.h>
#include <stddef.h>
struct A{ char a; int b; };
struct B{ int b; char a; };
int main(void){
  printf("A %zu pad %zu offset b %zu\n", sizeof(struct A), sizeof(struct A)-sizeof(char)-sizeof(int), offsetof(struct A,b));
  printf("B %zu\n", sizeof(struct B));
  return 0;
}
